INSERT INTO arm_app."visual_references" ("document_id", "source_path", "source_run_sha256", "source_record_sha256", "source_fields", "source_timestamps", "id", "uploadedBy", "usageCount", "name", "imageUrl", "storageKey", "uploadedByName", "tags", "isActive", "uploadedAt") SELECT split_part(s.path,'/',2) AS "document_id", s.path AS "source_path", s.run_sha256 AS "source_run_sha256", s.record_sha256 AS "source_record_sha256", (SELECT array_agg(key ORDER BY key) FROM jsonb_each(f)) AS "source_fields", (SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) FROM jsonb_each(f) WHERE value->>'type'='timestamp') AS "source_timestamps", ((arm_migration.decode_value(f->'id')) #>> '{}')::bigint AS "id", ((arm_migration.decode_value(f->'uploadedBy')) #>> '{}')::bigint AS "uploadedBy", ((arm_migration.decode_value(f->'usageCount')) #>> '{}')::bigint AS "usageCount", ((arm_migration.decode_value(f->'name')) #>> '{}')::text AS "name", ((arm_migration.decode_value(f->'imageUrl')) #>> '{}')::text AS "imageUrl", ((arm_migration.decode_value(f->'storageKey')) #>> '{}')::text AS "storageKey", ((arm_migration.decode_value(f->'uploadedByName')) #>> '{}')::text AS "uploadedByName", nullif(arm_migration.decode_value(f->'tags'),'null'::jsonb) AS "tags", ((arm_migration.decode_value(f->'isActive')) #>> '{}')::boolean AS "isActive", ((arm_migration.decode_value(f->'uploadedAt')) #>> '{}')::timestamptz AS "uploadedAt" FROM arm_migration.source_documents s CROSS JOIN LATERAL (SELECT s.raw_record::jsonb #> '{fields,value}' AS f) decoded WHERE s.run_sha256='449569bed5c4b9a108603ae7d14e5da8028255efb19f913b136f0eea4c882383' AND s.source_exists AND array_length(string_to_array(s.path,'/'),1)=2 AND split_part(s.path,'/',1)='visual_references';
DO $$ BEGIN
 IF EXISTS ((SELECT "document_id", "source_path", "source_run_sha256", "source_record_sha256", "source_fields", "source_timestamps", "id", "uploadedBy", "usageCount", "name", "imageUrl", "storageKey", "uploadedByName", "tags", "isActive", "uploadedAt" FROM arm_app."visual_references" EXCEPT SELECT split_part(s.path,'/',2) AS "document_id", s.path AS "source_path", s.run_sha256 AS "source_run_sha256", s.record_sha256 AS "source_record_sha256", (SELECT array_agg(key ORDER BY key) FROM jsonb_each(f)) AS "source_fields", (SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) FROM jsonb_each(f) WHERE value->>'type'='timestamp') AS "source_timestamps", ((arm_migration.decode_value(f->'id')) #>> '{}')::bigint AS "id", ((arm_migration.decode_value(f->'uploadedBy')) #>> '{}')::bigint AS "uploadedBy", ((arm_migration.decode_value(f->'usageCount')) #>> '{}')::bigint AS "usageCount", ((arm_migration.decode_value(f->'name')) #>> '{}')::text AS "name", ((arm_migration.decode_value(f->'imageUrl')) #>> '{}')::text AS "imageUrl", ((arm_migration.decode_value(f->'storageKey')) #>> '{}')::text AS "storageKey", ((arm_migration.decode_value(f->'uploadedByName')) #>> '{}')::text AS "uploadedByName", nullif(arm_migration.decode_value(f->'tags'),'null'::jsonb) AS "tags", ((arm_migration.decode_value(f->'isActive')) #>> '{}')::boolean AS "isActive", ((arm_migration.decode_value(f->'uploadedAt')) #>> '{}')::timestamptz AS "uploadedAt" FROM arm_migration.source_documents s CROSS JOIN LATERAL (SELECT s.raw_record::jsonb #> '{fields,value}' AS f) decoded WHERE s.run_sha256='449569bed5c4b9a108603ae7d14e5da8028255efb19f913b136f0eea4c882383' AND s.source_exists AND array_length(string_to_array(s.path,'/'),1)=2 AND split_part(s.path,'/',1)='visual_references') UNION ALL (SELECT split_part(s.path,'/',2) AS "document_id", s.path AS "source_path", s.run_sha256 AS "source_run_sha256", s.record_sha256 AS "source_record_sha256", (SELECT array_agg(key ORDER BY key) FROM jsonb_each(f)) AS "source_fields", (SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) FROM jsonb_each(f) WHERE value->>'type'='timestamp') AS "source_timestamps", ((arm_migration.decode_value(f->'id')) #>> '{}')::bigint AS "id", ((arm_migration.decode_value(f->'uploadedBy')) #>> '{}')::bigint AS "uploadedBy", ((arm_migration.decode_value(f->'usageCount')) #>> '{}')::bigint AS "usageCount", ((arm_migration.decode_value(f->'name')) #>> '{}')::text AS "name", ((arm_migration.decode_value(f->'imageUrl')) #>> '{}')::text AS "imageUrl", ((arm_migration.decode_value(f->'storageKey')) #>> '{}')::text AS "storageKey", ((arm_migration.decode_value(f->'uploadedByName')) #>> '{}')::text AS "uploadedByName", nullif(arm_migration.decode_value(f->'tags'),'null'::jsonb) AS "tags", ((arm_migration.decode_value(f->'isActive')) #>> '{}')::boolean AS "isActive", ((arm_migration.decode_value(f->'uploadedAt')) #>> '{}')::timestamptz AS "uploadedAt" FROM arm_migration.source_documents s CROSS JOIN LATERAL (SELECT s.raw_record::jsonb #> '{fields,value}' AS f) decoded WHERE s.run_sha256='449569bed5c4b9a108603ae7d14e5da8028255efb19f913b136f0eea4c882383' AND s.source_exists AND array_length(string_to_array(s.path,'/'),1)=2 AND split_part(s.path,'/',1)='visual_references' EXCEPT SELECT "document_id", "source_path", "source_run_sha256", "source_record_sha256", "source_fields", "source_timestamps", "id", "uploadedBy", "usageCount", "name", "imageUrl", "storageKey", "uploadedByName", "tags", "isActive", "uploadedAt" FROM arm_app."visual_references")) THEN RAISE EXCEPTION 'Value reconciliation failed: visual_references'; END IF;
END $$;

SELECT setval(pg_get_serial_sequence('arm_app."visual_references"','id'), greatest(coalesce((SELECT max(id)+1 FROM arm_app."visual_references"),1),coalesce((SELECT (raw_record::jsonb #>> '{fields,value,next,value}')::bigint FROM arm_migration.source_documents WHERE run_sha256='449569bed5c4b9a108603ae7d14e5da8028255efb19f913b136f0eea4c882383' AND path='_counters/visual_references'),1)), false);

INSERT INTO arm_migration.unresolved_notifications(source_path,run_sha256,reason,raw_record)
SELECT path, run_sha256, 'Recipient does not exist; original notification preserved', raw_record FROM arm_migration.source_documents s WHERE run_sha256='449569bed5c4b9a108603ae7d14e5da8028255efb19f913b136f0eea4c882383' AND path ~ '^notifications/[^/]+$' AND NOT EXISTS(SELECT 1 FROM arm_app.users u WHERE u.id=(s.raw_record::jsonb #>> '{fields,value,userId,value}')::bigint);
DO $$ DECLARE loaded bigint; expected bigint; BEGIN
 SELECT (SELECT count(*) FROM arm_app."roles")+(SELECT count(*) FROM arm_app."campuses")+(SELECT count(*) FROM arm_app."job_titles")+(SELECT count(*) FROM arm_app."users")+(SELECT count(*) FROM arm_app."org_areas")+(SELECT count(*) FROM arm_app."org_teams")+(SELECT count(*) FROM arm_app."org_memberships")+(SELECT count(*) FROM arm_app."campus_administradores")+(SELECT count(*) FROM arm_app."campus_equipos")+(SELECT count(*) FROM arm_app."campus_turnos")+(SELECT count(*) FROM arm_app."canciones")+(SELECT count(*) FROM arm_app."content")+(SELECT count(*) FROM arm_app."disponibilidades")+(SELECT count(*) FROM arm_app."feedback")+(SELECT count(*) FROM arm_app."fichas")+(SELECT count(*) FROM arm_app."ficha_changelog")+(SELECT count(*) FROM arm_app."notifications")+(SELECT count(*) FROM arm_app."onboarding")+(SELECT count(*) FROM arm_app."paletas")+(SELECT count(*) FROM arm_app."refresh_tokens")+(SELECT count(*) FROM arm_app."tipo_cambio")+(SELECT count(*) FROM arm_app."tipo_cambio_meta")+(SELECT count(*) FROM arm_app."visual_references") + (SELECT count(*) FROM arm_migration.unresolved_notifications WHERE run_sha256='449569bed5c4b9a108603ae7d14e5da8028255efb19f913b136f0eea4c882383') INTO loaded;
 SELECT count(*) INTO expected FROM arm_migration.source_documents WHERE run_sha256='449569bed5c4b9a108603ae7d14e5da8028255efb19f913b136f0eea4c882383' AND source_exists AND path NOT LIKE '_counters/%';
 IF loaded <> expected THEN RAISE EXCEPTION 'Total reconciliation failed'; END IF;
END $$;
INSERT INTO arm_migration.operational_loads(run_sha256,counts) VALUES ('449569bed5c4b9a108603ae7d14e5da8028255efb19f913b136f0eea4c882383', jsonb_build_object('roles', (SELECT count(*) FROM arm_app."roles"), 'campuses', (SELECT count(*) FROM arm_app."campuses"), 'job_titles', (SELECT count(*) FROM arm_app."job_titles"), 'users', (SELECT count(*) FROM arm_app."users"), 'org_areas', (SELECT count(*) FROM arm_app."org_areas"), 'org_teams', (SELECT count(*) FROM arm_app."org_teams"), 'org_memberships', (SELECT count(*) FROM arm_app."org_memberships"), 'campus_administradores', (SELECT count(*) FROM arm_app."campus_administradores"), 'campus_equipos', (SELECT count(*) FROM arm_app."campus_equipos"), 'campus_turnos', (SELECT count(*) FROM arm_app."campus_turnos"), 'canciones', (SELECT count(*) FROM arm_app."canciones"), 'content', (SELECT count(*) FROM arm_app."content"), 'disponibilidades', (SELECT count(*) FROM arm_app."disponibilidades"), 'feedback', (SELECT count(*) FROM arm_app."feedback"), 'fichas', (SELECT count(*) FROM arm_app."fichas"), 'ficha_changelog', (SELECT count(*) FROM arm_app."ficha_changelog"), 'notifications', (SELECT count(*) FROM arm_app."notifications"), 'onboarding', (SELECT count(*) FROM arm_app."onboarding"), 'paletas', (SELECT count(*) FROM arm_app."paletas"), 'refresh_tokens', (SELECT count(*) FROM arm_app."refresh_tokens"), 'tipo_cambio', (SELECT count(*) FROM arm_app."tipo_cambio"), 'tipo_cambio_meta', (SELECT count(*) FROM arm_app."tipo_cambio_meta"), 'visual_references', (SELECT count(*) FROM arm_app."visual_references"), 'unresolved_notifications', (SELECT count(*) FROM arm_migration.unresolved_notifications)));
COMMIT;
SELECT counts FROM arm_migration.operational_loads WHERE run_sha256='449569bed5c4b9a108603ae7d14e5da8028255efb19f913b136f0eea4c882383';
